'use strict';
const $ = s => document.querySelector(s);
const titles = ['함께 하는 쇼핑','사용자의 질문','해결책 살펴보기','KVM 이해하기','나의 환경과 기준','제품 후보 탐색','구매 경로·가격 조사'];
const state = {step:0,max:0,solution:'kvm',tab:'concept',question:'두 대의 컴퓨터를 하나의 모니터에서 전환하면서 사용하고 싶어요.',computers:'맥북, Windows 데스크톱',monitor:'모니터 1대 · 모델/해상도 확인 필요',priorities:['가격','배송·AS','사용 편의성'],route:0};
const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const positions = [[32,35,210,64],[32,140,210,64],[300,140,220,64],[300,260,220,64],[32,380,210,64],[300,380,220,64],[300,565,220,64]];
function graph(){
 const paths=['M137 99 V140','M242 172 H300','M410 204 V260','M410 324 V350 H137 V380','M242 412 H300','M410 444 V565'];
 const captions=['발표 시작','원하는 사용 경험','가능한 방법 비교','개념과 종류','장비 · 우선순위','후보별로 나누어 탐색','구매 옵션까지 연결'];
 $('#map').innerHTML=`<svg viewBox="0 0 555 660" role="group" aria-label="구매 의사결정 흐름">${paths.map((d,i)=>`<path class="edge ${state.max>i?'reached':''}" d="${d}"/>`).join('')}${state.max>=5?'<path class="edge reached" d="M410 444 V480 H125 V510 M410 480 H240 V510 M410 480 V510"/><text class="branch-note" x="125" y="530" text-anchor="middle">후보 02 · 미정</text><text class="branch-note" x="255" y="530" text-anchor="middle">후보 03 · 미정</text><text class="branch-note" x="410" y="530" text-anchor="middle">UGREEN KVM</text>':''}${positions.map(([x,y,w,h],i)=>`<g class="node ${i<=state.max?'unlocked':''} ${i===state.step?'active':''}" ${i<=state.max?`role="button" tabindex="0" data-step="${i}"`:'aria-disabled="true"'} aria-label="${i+1}. ${titles[i]}${i===state.step?' 현재 단계':''}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12"/><circle cx="${x+25}" cy="${y+25}" r="12"/><text class="number" x="${x+25}" y="${y+29}" text-anchor="middle">${i+1}</text><text x="${x+46}" y="${y+27}">${titles[i]}</text><text class="node-sub" x="${x+46}" y="${y+46}">${captions[i]}</text></g>`).join('')}</svg>`;
 document.querySelectorAll('[data-step]').forEach(el=>{const go=()=>navigate(Number(el.dataset.step));el.addEventListener('click',go);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}})});
}
function intro(){return `<span class="tag">FUTURE COMMERCE / TRACK A</span><h2>나에게 더 잘 맞는 선택.<br><span class="accent">이해하면서 함께 고르는 쇼핑.</span></h2><p class="lead">배경지식이 없어도, 내가 무엇을 선택하는지 알 수 있도록.</p><div class="intro-pair"><div><div class="small">빠르고 편리한 쇼핑</div><strong>요청 → 추천 → 구매</strong></div><div><div class="small">우리가 만들고 싶은 경험</div><strong>질문하고, 이해하고,<br>나에게 맞게 선택하기</strong></div></div><div class="statement"><strong>“이 제품을 사면,<br>내 환경은 어떻게 달라질까?”</strong><p>제품 이름을 아는 것에서, 선택의 결과를 이해하는 것으로.</p></div><div class="scene"><div class="scene-icon">⌘</div><div><strong>오늘의 이야기 · 데스크테리어를 시작하는 초보자</strong><p class="small" style="margin:4px 0">배경지식 없이 두 대의 컴퓨터를 함께 사용하려고 합니다.</p></div></div>`}
function question(){return `<span class="tag">01 / 원하는 경험에서 시작</span><h2>어떤 환경을<br>만들고 싶으세요?</h2><p class="lead">제품 이름을 몰라도 괜찮아요. 하고 싶은 일을 들려주세요.</p><label class="field">나의 요청<textarea id="question" maxlength="500">${escapeHTML(state.question)}</textarea></label><div class="setup"><div class="setup-row"><div class="device">컴퓨터 A</div><div class="device">컴퓨터 B</div></div><div class="setup-line">↓ ↓</div><div class="device" style="width:180px;margin:auto">하나의 모니터</div></div><div class="why">먼저 원하는 사용 경험을 이해해요.<br>이 요청을 해결하는 방법은 하나만 있는 게 아닐 수 있어요.</div>`}
function solution(){return `<span class="tag">02 / 해결책 선택</span><h2>어떤 방식으로<br>연결할 수 있을까요?</h2><p class="lead">모니터 전환과 입력장치 공유를 어떻게 해결할지 살펴봐요.</p><div class="choices"><button class="choice" data-solution="kvm" aria-pressed="${state.solution==='kvm'}"><span class="radio"></span><span><strong>KVM 장치 구매</strong><span class="desc">모니터와 키보드·마우스 연결을 컴퓨터 사이에서 전환하는 방법을 살펴봐요. 지원 범위는 제품마다 확인해요.</span></span></button><button class="choice" data-solution="software" aria-pressed="${state.solution==='software'}"><span class="radio"></span><span><strong>프로그램 활용</strong><span class="desc">소프트웨어 기반의 공유 방법도 있어요. 화면 전환까지 원하는 방식으로 가능한지는 별도 확인이 필요해요.</span></span></button></div>${state.solution==='software'?'<div class="callout">이 구상안은 KVM 구매 경로까지 설계되어 있어요. 프로그램 경로의 상세 내용은 아직 준비하지 않았어요.</div>':'<div class="why">장치를 바로 추천하기 전에,<br>KVM이 무엇인지 함께 이해해볼게요.</div>'}`}
function learn(){return `<span class="tag">03 / 선택에 필요한 배경지식</span><h2>KVM을 이해하면<br>비교 기준이 보여요.</h2><div class="tabs" role="tablist" aria-label="KVM 설명"><button role="tab" aria-selected="${state.tab==='concept'}" class="${state.tab==='concept'?'selected':''}" data-tab="concept">① 개념</button><button role="tab" aria-selected="${state.tab==='types'}" class="${state.tab==='types'?'selected':''}" data-tab="types">② 종류와 확인점</button></div>${state.tab==='concept'?`<div class="definition"><strong>Keyboard · Video · Mouse</strong><p>여러 컴퓨터가 모니터와 키보드·마우스를 공유하도록 연결하고, 사용할 컴퓨터를 전환하는 장치예요.</p></div><div class="setup"><div class="setup-row"><div class="device">컴퓨터 A</div><div class="device">컴퓨터 B</div></div><div class="setup-line">↓ ↓</div><div class="switch">KVM 스위치</div><div class="setup-line">↓</div><div class="setup-row"><div class="device">모니터</div><div class="device">키보드 · 마우스</div></div></div><p class="small">연결 개념을 보여주는 도식이에요. 실제 포트와 케이블 구성은 장비 및 제품 확인 후 달라져요.</p>`:`<div class="type-list"><div><strong>영상 연결 방식</strong><p>내 컴퓨터와 모니터의 단자에 맞는 연결인지 확인해야 해요.</p></div><div><strong>연결할 컴퓨터와 모니터 수</strong><p>필요한 연결 수를 지원하는 제품인지 살펴봐요.</p></div><div><strong>화면 조건과 주변기기</strong><p>원하는 해상도·주사율과 사용할 입력장치의 지원 여부를 확인해요.</p></div></div><div class="why">같은 KVM이라도 내 장비에 따라 필요한 구성이 달라져요.<br>다음 단계에서 나의 환경과 우선순위를 정리해요.</div>`}`}
function environment(){return `<span class="tag">04 / 나의 상황 파악</span><h2>당신의 책상에 맞춰<br>살펴볼게요.</h2><p class="lead">예시를 수정하고, 중요하게 생각하는 순서를 정해주세요.</p><label class="field">두 컴퓨터의 종류<input id="computers" value="${escapeHTML(state.computers)}" placeholder="예: 맥북, Windows 데스크톱" maxlength="180"></label><label class="field">모니터의 종류와 개수<input id="monitor" value="${escapeHTML(state.monitor)}" placeholder="예: 모니터 1대, 모델명" maxlength="180"></label><div class="priority-title">중요하게 생각하는 가치 <span class="small">· 위쪽일수록 중요해요</span></div>${state.priorities.map((p,i)=>`<div class="priority-row"><span class="rank">${i+1}</span><span class="name">${p}</span><button data-move="${i},-1" aria-label="${p} 우선순위 올리기" ${i===0?'disabled':''}>↑</button><button data-move="${i},1" aria-label="${p} 우선순위 내리기" ${i===state.priorities.length-1?'disabled':''}>↓</button></div>`).join('')}<p class="small">모르는 정보는 ‘확인 필요’로 남겨도 괜찮아요.</p>`}
function candidates(){return `<span class="tag">05 / 제품별 탐색으로 확장</span><h2>이제 제품별로<br>가능성을 펼쳐봐요.</h2><p class="lead">나의 조건을 기준으로 후보를 살펴보는 단계예요.</p><div class="summary">${escapeHTML(state.computers)} / ${escapeHTML(state.monitor)}<br>우선순위: ${state.priorities.join(' → ')}</div><div class="candidate featured"><div class="meta"><span>구상안에 적힌 후보</span><span>01</span></div><h3>UGREEN KVM</h3><p>모델 번호는 원문 확인 필요 · 제품 사양과 적합성 미검증</p><button id="candidate-detail">구매 경로 살펴보기 →</button></div><div class="candidate"><div class="meta"><span>후보 02</span><span>미정</span></div><p>구상안의 두 번째 제품 자리</p></div><div class="candidate"><div class="meta"><span>후보 03</span><span>미정</span></div><p>구상안의 세 번째 제품 자리</p></div><p class="small">현재는 발표용 흐름 시연이에요. 입력 조건으로 실제 제품을 검색하거나 추천하지 않아요.</p>`}
function routes(){return `<span class="tag">06 / 구매 경로와 가격 조사</span><h2>같은 제품도<br>구매 옵션은 달라져요.</h2><p class="lead">UGREEN KVM의 구매 경로를 펼쳐 확인하는 화면이에요.</p>${[1,2,3].map((n)=>`<details class="route" ${state.route===n?'open':''}><summary>구매 옵션 ${n}<span>조사 전</span></summary><div class="route-body"><dl><dt>구매처</dt><dd>확인 필요</dd><dt>상품·옵션 가격</dt><dd>확인 필요</dd><dt>결제 경로·혜택</dt><dd>확인 필요</dd></dl><p class="small">원문에 옵션의 구체적인 내용은 아직 적혀 있지 않아요.</p></div></details>`).join('')}<div class="end"><strong>여기까지가 이번 구상안의 범위예요.</strong><p>후속 비교와 최종 구매 단계는 다음 논의에서 이어갑니다.</p></div>`}
function save(){if($('#question'))state.question=$('#question').value;if($('#computers'))state.computers=$('#computers').value;if($('#monitor'))state.monitor=$('#monitor').value;}
function navigate(step){save();state.step=step;state.max=Math.max(state.max,step);render();$('#content').focus({preventScroll:true});}
function render(){graph();$('#step-label').textContent=titles[state.step];$('#step-count').textContent=`${String(state.step+1).padStart(2,'0')} / 07`;$('#progress-fill').style.width=`${(state.step+1)/7*100}%`;$('#content').innerHTML=[intro,question,solution,learn,environment,candidates,routes][state.step]();$('#back').disabled=state.step===0;$('#next').disabled=state.step===6||(state.step===2&&state.solution==='software');$('#next').innerHTML=state.step===6?'구상안 끝':state.step===0?'함께 시작하기 <span>→</span>':state.step===3&&state.tab==='concept'?'종류도 이해하기 <span>→</span>':'다음 <span>→</span>';$('#nav-hint').textContent=state.step===6?'첫 초안 · 여기까지':state.step===0?'버튼을 누르며 발표하세요':'입력과 선택이 흐름에 반영돼요';
 document.querySelectorAll('[data-solution]').forEach(el=>el.onclick=()=>{state.solution=el.dataset.solution;if(state.solution==='software')state.max=Math.min(state.max,2);render();});document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{state.tab=el.dataset.tab;render();});document.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>{save();const [i,d]=el.dataset.move.split(',').map(Number);[state.priorities[i],state.priorities[i+d]]=[state.priorities[i+d],state.priorities[i]];render();});if($('#candidate-detail'))$('#candidate-detail').onclick=()=>navigate(6);document.querySelectorAll('.route').forEach((el,i)=>el.addEventListener('toggle',()=>{if(el.open)state.route=i+1;}));$('#announcement').textContent=`${state.step+1}단계, ${titles[state.step]}`;
}
$('#next').onclick=()=>{if($('#next').disabled)return;if(state.step===3&&state.tab==='concept'){state.tab='types';render();return;}if(state.step===1&&!$('#question').value.trim()){$('#question').setCustomValidity('원하는 사용 경험을 입력해주세요.');$('#question').reportValidity();$('#question').oninput=()=>$('#question').setCustomValidity('');return;}navigate(state.step+1);};
$('#back').onclick=()=>{if(state.step>0)navigate(state.step-1)};
$('#reset').onclick=()=>{Object.assign(state,{step:0,max:0,solution:'kvm',tab:'concept',question:'두 대의 컴퓨터를 하나의 모니터에서 전환하면서 사용하고 싶어요.',computers:'맥북, Windows 데스크톱',monitor:'모니터 1대 · 모델/해상도 확인 필요',priorities:['가격','배송·AS','사용 편의성'],route:0});render();};
$('.brand').onclick=e=>{e.preventDefault();navigate(0);};
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('#announcement').textContent='브라우저 전체 화면 단축키 F11을 사용해주세요.'}};
document.addEventListener('fullscreenchange',()=>$('#fullscreen').textContent=document.fullscreenElement?'전체 화면 종료 ↙':'전체 화면 ↗');
render();
